 $q=$db->prepare("SELECT d.id department_id,cs.id subject_id,cs.name subject_name,c.name class_name,COUNT(CASE WHEN x.id IS NOT NULL THEN r.id END) assessed_scores,AVG(CASE WHEN x.id IS NOT NULL AND r.max_score>0 THEN 100*r.score/r.max_score END) average_percent FROM departments d JOIN department_subjects ds ON ds.department_id=d.id AND ds.school_id=d.school_id JOIN school_class_subjects cs ON cs.id=ds.class_subject_id JOIN school_classes c ON c.id=cs.class_id AND c.school_id=d.school_id LEFT JOIN pupil_results r ON r.school_id=d.school_id AND r.class_level=c.name AND r.subject=cs.name LEFT JOIN school_exams x ON x.school_id=r.school_id AND x.name=r.exam_name AND x.academic_year=r.academic_year AND x.status='results_published' AND (x.class_id IS NULL OR x.class_id=c.id) AND (x.subject_id IS NULL OR x.subject_id=cs.id) WHERE d.school_id=? AND d.department_type='academic'$deptFilter GROUP BY d.id,cs.id,cs.name,c.name ORDER BY d.name,c.name,cs.name");$q->execute($deptParams);$performance=$q->fetchAll();
